package dev.veld.jetbrains

import com.intellij.openapi.project.Project
import com.intellij.openapi.vfs.VirtualFile
import com.jetbrains.jsonSchema.extension.JsonSchemaFileProvider
import com.jetbrains.jsonSchema.extension.JsonSchemaProviderFactory
import com.jetbrains.jsonSchema.extension.SchemaType

/**
 * Maps `veld.toml` to the bundled JSON Schema (generated by `cargo xtask codegen` from the config
 * spec). Loaded only when the JSON plugin is present (see veld-json-schema.xml). Completion and
 * documentation in the TOML editor need the IDE's TOML plugin, which provides the TOML editor.
 */
class VeldTomlSchemaProviderFactory : JsonSchemaProviderFactory {
    override fun getProviders(project: Project): List<JsonSchemaFileProvider> = listOf(VeldTomlSchemaProvider())
}

class VeldTomlSchemaProvider : JsonSchemaFileProvider {
    override fun isAvailable(file: VirtualFile): Boolean = file.name == FILE_NAME

    override fun getName(): String = "veld.toml"

    override fun getSchemaFile(): VirtualFile? =
        JsonSchemaProviderFactory.getResourceFile(VeldTomlSchemaProvider::class.java, SCHEMA_RESOURCE)

    override fun getSchemaType(): SchemaType = SchemaType.embeddedSchema

    companion object {
        const val FILE_NAME = "veld.toml"
        const val SCHEMA_RESOURCE = "/schemas/veld.toml.schema.json"
    }
}
